def main():
    global AMC_TOPICS, MCCQE_TOPICS
    AMC_TOPICS = AMC_TOPICS[:100]
    MCCQE_TOPICS = (MCCQE_TOPICS + MCCQE_ADDITIONAL)[:100]

    print(f"Total AMC topics: {len(AMC_TOPICS)}")
    print(f"Total MCCQE topics: {len(MCCQE_TOPICS)}")

    assert len(AMC_TOPICS) == 100, f"Expected 100 AMC topics, got {len(AMC_TOPICS)}"
    assert len(MCCQE_TOPICS) == 100, f"Expected 100 MCCQE topics, got {len(MCCQE_TOPICS)}"

    for title, subj, sys_name, snip, g_name, g_url in AMC_TOPICS:
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} in {title}"
        assert g_url.startswith("https://"), f"Invalid url {g_url} in {title}"
        assert len(snip) > 20

    for title, subj, sys_name, snip, g_name, g_url in MCCQE_TOPICS:
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} in {title}"
        assert g_url.startswith("https://"), f"Invalid url {g_url} in {title}"
        assert len(snip) > 20

    out_path = os.path.join(os.path.dirname(__file__), "mega42_topics_a.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 42 Topics Part A\n")
        f.write("# AMC (100 topics) + MCCQE (100 topics)\n\n")
        f.write(f"AMC_TOPICS = {repr(AMC_TOPICS)}\n\n")
        f.write(f"MCCQE_TOPICS = {repr(MCCQE_TOPICS)}\n")
    print(f"Successfully generated {out_path}!")

if __name__ == "__main__":
    main()
